const labels = [
 'جارٍ تحميل بيانات الحساب…','حفظ الاسم','الاسم الظاهر واسم المستخدم','الاسم الظاهر','اسم المستخدم (اختياري)',
 'اسم المستخدم من 3 إلى 30 حرفًا لاتينيًا أو رقمًا أو شرطة سفلية، ويبدأ بحرف. لا يغيّر البريد أو طريقة الدخول.',
 'تغيّر الحساب. أعد فتح صفحة الحساب.','تعذّر تحميل بيانات الحساب. لم تتغير بياناتك؛ أعد فتح الصفحة للمحاولة.','حُفظ الاسم في حسابك.',
 'اسم المستخدم مستخدم بالفعل؛ اختر اسمًا آخر.','تغيّرت بيانات الحساب في جلسة أخرى. احتفظ بتعديلاتك وأعد فتح الصفحة قبل الحفظ.',
 'تحقق من الاسم واسم المستخدم؛ بعض الأسماء الإدارية محجوزة.','تعذّر تأكيد الحفظ؛ تحقق من بياناتك قبل إعادة المحاولة.',
 'سنة الميلاد الميلادية الاختيارية','الموافقة على إحصاءات العمر الإجمالية','حفظ اختيار إحصاءات العمر','المشاركة الاختيارية في إحصاءات الجمهور','سنة الميلاد الميلادية (اختيارية)',
 'أوافق على استخدام سنة ميلادي في إحصاءات عمر إجمالية لتحسين محتوى الخزانة والتعريف بها.',
 'لا تظهر سنة ميلادك في صفحات الحسابات أو التقارير الإدارية. يمكنك إلغاء الموافقة ثم الحفظ لحذف السنة من بيانات الإحصاء. المشاركة ليست شرطًا لاستخدام الموقع.',
 'أدخل سنة ميلاد صحيحة أو ألغِ الموافقة.','حُفظت موافقتك الاختيارية.','أُلغيت الموافقة وحُذفت سنة الميلاد من بيانات الإحصاء.',
 'تغير اختيارك في جلسة أخرى؛ أعد فتح الصفحة قبل الحفظ.','تعذّر الحفظ. لم نؤكد تغيير اختيارك.','إعداد إحصاءات العمر غير متاح الآن.',
] as const
function row(text:string):Record<string,string>{const values=text.split('|').map(v=>v.trim());if(values.length!==labels.length)throw Error(`Account locale length: ${values.length}`);return Object.fromEntries(labels.map((key,index)=>[key,values[index]!]))}
